import{_ as e,o as a,c as i,a5 as t}from"./chunks/framework.DGp912Ge.js";const u=JSON.parse('{"title":"Image Echo — C++ Example","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/sdk/cpp/image-echo.md","filePath":"software/sdk/cpp/image-echo.md","lastUpdated":1784194075000}'),n={name:"software/sdk/cpp/image-echo.md"};function o(l,s,r,p,h,c){return a(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="image-echo-—-c-example" tabindex="-1">Image Echo — C++ Example <a class="header-anchor" href="#image-echo-—-c-example" aria-label="Permalink to &quot;Image Echo — C++ Example&quot;">​</a></h1><p><strong>Source</strong>: <code>rbq_sdk/cpp/example/src/rbq_image_echo.cpp</code></p><p>A minimal, read-only diagnostic that <strong>subscribes to a compressed camera topic</strong> and prints the receive rate, last frame size, and image format once per second. Use it to confirm a camera stream is actually being published and is reachable from your SDK host.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>The program:</p><ol><li>Reads the topic name from <code>argv[1]</code> (default <code>rt/rbq/vision/sensor_4/rgb/compressed</code>).</li><li>Initializes the DDS <code>ChannelFactory</code> and creates a <code>Subscriber&lt;CompressedImage_&gt;</code>.</li><li>On every received sample, updates a counter plus the last byte size and image format.</li><li>Once per second, prints elapsed time, total samples, the 1-second rate, last frame size, and format.</li><li>Exits cleanly on <code>Ctrl+C</code> (SIGINT/SIGTERM), printing the total sample count.</li></ol><p>It never publishes, so it is safe to run alongside a live robot or the simulator.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>RBQ SDK built and installed — see <a href="/RBQ/software/sdk/cpp/overview.html">C++ SDK Overview</a>.</li><li>A publisher of the compressed image topic running — the robot&#39;s vision stack, or the MuJoCo simulator with vision (<code>bash scripts/sim.bash --vision</code>).</li></ul><h2 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h2><p>From <code>rbq_sdk/cpp/example/</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div><p>Binary: <code>bin/rbq_image_echo</code></p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><h3 id="on-the-real-robot" tabindex="-1">On the real robot <a class="header-anchor" href="#on-the-real-robot" aria-label="Permalink to &quot;On the real robot&quot;">​</a></h3><p>The defaults are set for the robot, so run it as-is:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_image_echo</span></span></code></pre></div><p>This subscribes to <code>rt/rbq/vision/sensor_4/rgb/compressed</code> (the front camera) over the robot&#39;s <code>enp45s0</code> interface — both are baked into the example (<code>ChannelFactory::Instance().Init(0, &quot;enp45s0&quot;)</code> in <code>main()</code>, plus the default topic). To watch a different camera, pass its topic as the first argument.</p><h3 id="in-the-mujoco-simulator" tabindex="-1">In the MuJoCo simulator <a class="header-anchor" href="#in-the-mujoco-simulator" aria-label="Permalink to &quot;In the MuJoCo simulator&quot;">​</a></h3><p>The simulator runs on your PC instead of on the robot, so two things differ.</p><p><strong>1. Launch the sim on a network interface you actually have.</strong> Without <code>-i</code>, <code>sim.bash --vision</code> leaves the vision/camera publisher on the robot&#39;s <code>enp45s0</code>, which doesn&#39;t exist on your PC — so the client finds nothing. List your interfaces with <code>ip link</code> (e.g. <code>enp3s0</code>) and pass it, so the whole sim shares it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enp3s0</span></span></code></pre></div><p><strong>2. Point this client at the same interface, then run it.</strong> The interface is hard-coded in the example&#39;s source, so override it with a CycloneDDS config. The SDK only uses <code>CYCLONEDDS_URI</code> when it is set, so <strong>create the file first</strong> (replacing <code>enp3s0</code> with your interface):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/cyclonedds.xml</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;EOF&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;?xml version=&quot;1.0&quot; encoding=&quot;utf-8&quot; ?&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;CycloneDDS xmlns=&quot;https://cdds.io/config&quot;&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &lt;Domain Id=&quot;any&quot;&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &lt;General&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &lt;Interfaces&gt;&lt;NetworkInterface name=&quot;enp3s0&quot; priority=&quot;default&quot; multicast=&quot;default&quot;/&gt;&lt;/Interfaces&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &lt;AllowMulticast&gt;spdp&lt;/AllowMulticast&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &lt;/General&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &lt;/Domain&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;/CycloneDDS&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CYCLONEDDS_URI</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">file:///tmp/cyclonedds.xml</span></span></code></pre></div><p>Then run it. Cameras use <strong>numeric</strong> ids on both the robot and the sim — <code>sensor_4</code> is the front camera, <code>sensor_5</code> the rear:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_image_echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rt/rbq/vision/sensor_4/rgb/compressed</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # front camera</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_image_echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rt/rbq/vision/sensor_5/rgb/compressed</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # rear camera</span></span></code></pre></div><p><code>sensor_4</code> is the <strong>front</strong> camera and <code>sensor_5</code> is the <strong>rear</strong> camera; <code>sensor_0</code>–<code>sensor_3</code> publish only <code>depth</code> and <code>ir</code>.</p><blockquote><p>The sim and this client must use the <strong>same</strong> interface — if they differ, or if you leave both on <code>lo</code> (usually not multicast-capable), you&#39;ll see <code>rate=0 Hz</code>.</p></blockquote><h2 id="example-output" tabindex="-1">Example output <a class="header-anchor" href="#example-output" aria-label="Permalink to &quot;Example output&quot;">​</a></h2><p>Against the MuJoCo simulator (<code>sim.bash --vision</code>), subscribing to <code>sensor_4</code> (front camera):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[rbq_image_echo] subscribed to &#39;rt/rbq/vision/sensor_4/rgb/compressed&#39;</span></span>
<span class="line"><span>[rbq_image_echo] waiting for samples (Ctrl+C to exit)...</span></span>
<span class="line"><span>[rbq_image_echo] 1.0s  total=15  rate=15 Hz  last=13053 bytes  fmt=&#39;jpeg&#39;</span></span>
<span class="line"><span>[rbq_image_echo] 2.0s  total=29  rate=14 Hz  last=13080 bytes  fmt=&#39;jpeg&#39;</span></span>
<span class="line"><span>[rbq_image_echo] 3.0s  total=44  rate=15 Hz  last=13067 bytes  fmt=&#39;jpeg&#39;</span></span>
<span class="line"><span>[rbq_image_echo] exiting, total samples = 44</span></span></code></pre></div><p>A steady rate with non-zero byte sizes and <code>fmt=&#39;jpeg&#39;</code> confirms the stream is live. <code>rate=0 Hz</code> means no publisher was found on that topic/interface — check the topic name and the DDS interface.</p>`,32)])])}const g=e(n,[["render",o]]);export{u as __pageData,g as default};
